entries[64643] = { ["name"] = "Königin Azsharas Morgenmantel", ["text"] = "Accountgebunden\nBrust Stoff\n258 Rüstung\n+27 Ausdauer\n+41 Intelligenz\nHaltbarkeit 165 / 165\nBenötigt Stufe 51\nAnlegen: Erhöht die Tempowertung um 23.\n\"Die Gerüchte über den schlechten Modegeschmack der Hochgeborenen scheinen der Wahrheit zu entsprechen.\"\nVerkaufspreis:" }
entries[64644] = { ["name"] = "Kopfputz des ersten Schamanen", ["text"] = "Accountgebunden\nKopf Kette\n720 Rüstung\n+39 Beweglichkeit\n+21 Ausdauer\n\nRoter Sockel\nBlauer Sockel\nGelber Sockel\nSockelbonus: +6 Ausdauer\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 61\nAnlegen: Erhöht die kritische Trefferwertung um 22.\nAnlegen: Erhöht die Trefferwertung um 22.\nBenutzen: Gestattet es Euch, weit in die Ferne zu blicken. (1 Min Abklingzeit)" }
entries[64645] = { ["name"] = "Tyrandes Lieblingspuppe", ["text"] = "Accountgebunden\nEinzigartig anlegbar\nSchmuck\n+321 Intelligenz\nBenötigt Stufe 85\nAnlegen: Gewinnt 20% der Grundmanakosten Eurer Zauber zurück und speichert es in der Puppe, um sie zu einem späteren Zeitpunkt freizugeben. Es können maximal 4200 Mana gespeichert werden.\nBenutzen: Entfesselt das gesamte in der Puppe gesammelte Mana, wodurch Ihr Mana in entsprechende Höhe gewinnt und allen Gegnern im Umkreis von 15 Metern pro Manapunkt 1 Arkanschaden zufügt. (1 Min Abklingzeit)" }
